 "content": "from collections import deque


def transform(grid):
    """Slide every monochrome connected object right until blocked."""
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen
                            and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        cells.add((ny, nx))
                        q.append((ny, nx))
            objects.append((color, cells))

    # Advance all objects one cell at a time; only cells occupied by a different
    # object prevent a move. Simultaneous updates let objects follow one another.
    while True:
        owner = {cell: i for i, (_, cells) in enumerate(objects) for cell in cells}
        moving = []
        for i, (_, cells) in enumerate(objects):
            can_move = all(c + 1 < w and owner.get((r, c + 1), i) == i
                           for r, c in cells)
            moving.append(can_move)
        if not any(moving):
            break
        objects = [(color, {(r, c + int(moving[i])) for r, c in cells})
                   for i, (color, cells) in enumerate(objects)]

    out = [[0] * w for _ in range(h)]
    for color, cells in objects:
        for r, c in cells:
            out[r][c] = color
    return out
